window.ScripturaLexicons.BDAG_PART_0192 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-01\" data-source=\"BDAG\" data-search=\"καταπίμπρημι verbo reduzir a cinzas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταπίμπρημι</td><td>verbo</td><td>reduzir a cinzas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-02\" data-source=\"BDAG\" data-search=\"καταπίνω verbo engolir; tragar; aniquilar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταπίνω</td><td>verbo</td><td>engolir; tragar; aniquilar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-03\" data-source=\"BDAG\" data-search=\"καταπίπτω verbo cair; tombar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταπίπτω</td><td>verbo</td><td>cair; tombar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-04\" data-source=\"BDAG\" data-search=\"καταπιστεύω verbo confiar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταπιστεύω</td><td>verbo</td><td>confiar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-05\" data-source=\"BDAG\" data-search=\"καταπλέω verbo navegar em direção à costa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταπλέω</td><td>verbo</td><td>navegar em direção à costa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-06\" data-source=\"BDAG\" data-search=\"κατάπληξις, εως, ἡ substantivo feminino pavor; terror BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατάπληξις, εως, ἡ</td><td>substantivo feminino</td><td>pavor; terror</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-07\" data-source=\"BDAG\" data-search=\"καταπλήσσω verbo espantar; assombrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταπλήσσω</td><td>verbo</td><td>espantar; assombrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-08\" data-source=\"BDAG\" data-search=\"καταπονέω verbo oprimir; atormentar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταπονέω</td><td>verbo</td><td>oprimir; atormentar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-09\" data-source=\"BDAG\" data-search=\"καταποντίζω verbo submergir; afogar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταποντίζω</td><td>verbo</td><td>submergir; afogar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-10\" data-source=\"BDAG\" data-search=\"κατάρα, ας, ἡ substantivo feminino maldição; imprecação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατάρα, ας, ἡ</td><td>substantivo feminino</td><td>maldição; imprecação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-11\" data-source=\"BDAG\" data-search=\"καταράομαι verbo depoente amaldiçoar; imprecar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταράομαι</td><td>verbo depoente</td><td>amaldiçoar; imprecar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-12\" data-source=\"BDAG\" data-search=\"καταργέω verbo anular; abolir; libertar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταργέω</td><td>verbo</td><td>anular; abolir; libertar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-13\" data-source=\"BDAG\" data-search=\"καταριθμέω verbo enumerar; incluir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταριθμέω</td><td>verbo</td><td>enumerar; incluir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-14\" data-source=\"BDAG\" data-search=\"καταρρέω verbo escorrer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταρρέω</td><td>verbo</td><td>escorrer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-15\" data-source=\"BDAG\" data-search=\"καταρτίζω verbo restaurar; completar; preparar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταρτίζω</td><td>verbo</td><td>restaurar; completar; preparar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-16\" data-source=\"BDAG\" data-search=\"κατάρτισις, εως, ἡ substantivo feminino aperfeiçoamento; amadurecimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατάρτισις, εως, ἡ</td><td>substantivo feminino</td><td>aperfeiçoamento; amadurecimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-17\" data-source=\"BDAG\" data-search=\"καταρτισμός, οῦ, ὁ substantivo masculino capacitação; preparação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταρτισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>capacitação; preparação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-18\" data-source=\"BDAG\" data-search=\"κατασβέννυμι verbo apagar; extinguir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατασβέννυμι</td><td>verbo</td><td>apagar; extinguir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-19\" data-source=\"BDAG\" data-search=\"κατασείω verbo agitar; fazer sinal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατασείω</td><td>verbo</td><td>agitar; fazer sinal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0192-20\" data-source=\"BDAG\" data-search=\"κατασκάπτω verbo demolir; arrasar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατασκάπτω</td><td>verbo</td><td>demolir; arrasar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0192-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταπίμπρημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">aoristo, 3ª pessoa do singular, <span class=\"greek\">κατέπρησεν</span> (<span class=\"greek\">πίμπρημι</span>, «queimar, consumir pelo fogo»; Polyb., Polyaenus+; Philo, Div. Rer. Her. 296; Joseph.; Sb 8246, 46 [século IV d.C.]; B-D-F §101, 69) reduzir a cinzas <span class=\"greek\">κατέπ</span>[<span class=\"greek\">ρ</span>]<span class=\"greek\">ησεν</span> como variante textual na margem do P72 em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:6</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταπίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro <span class=\"greek\">καταπίομαι</span> (LXX; En 101:5); 2º aoristo <span class=\"greek\">κατέπιον</span>. Na voz passiva: 1º aoristo <span class=\"greek\">κατεπόθην</span>; perfeito, 3ª pessoa do singular, <span class=\"greek\">καταπέποται</span> (AcPlCor 2:29) (veja <span class=\"greek\">πίνω</span>; desde Hesíodo e Heródoto; Íon de Quios, Fgm. 31 L. referente ao apetite voraz de Héracles) no corpus aqui considerado, frequentemente empregado em imagens figuradas, tanto a respeito de líquidos quanto de sólidos</p><p class=\"entry-text\"> ① beber inteiramente, engolir, tragar <span class=\"greek\">τὶ</span>, alguma coisa, em linguagem figurada (referente à terra, que absorve a água Pla., Critias 111d; Diod S 1, 32, 4) <span class=\"greek\">ἤνοιξεν ἡ γῆ τὸ στόμα αὐτῆς καὶ κατέπιεν τὸν ποταμόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:16</a> (Philostephanus Hist. [século III a.C.], Fgm. 23 [ed. CMüller III 1849 p. 32 <span class=\"greek\">ποταμὸς ὑπὸ γῆς καταπίνεται</span>; Simplício, comentário a Epict. p. 95, 35; cf. Num 16:30, 32). <span class=\"greek\">Δαθὰν καὶ Ἀβιρὼν καὶ Κόρε</span>, <span class=\"greek\">πῶς</span> … <span class=\"greek\">κατεπόθησαν ἅπαντες</span> GJs 9:2 (cf. Num 16:32). <span class=\"greek\">τὴν κάμηλον κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:24</a> (Just., D. 112, 4; quanto ao camelo, veja <span class=\"greek\">κώνωψ</span>.)</p><p class=\"entry-text\"> ② destruir inteiramente, na figura de alguém que devora ou engole alguma coisa</p><p class=\"entry-text\"> ⓐ devorar (Hes., Theog. 459 <span class=\"greek\">υἱούς</span>. Referente a animais que devoram Tob 6:2; Jon 2:1; Jos., Ant. 2, 246; Ath. 34, 2) <span class=\"greek\">Ἰωνᾶς</span> … <span class=\"greek\">εἰς κῆτος καταπέποται</span> AcPlCor 2:29; o diabo, como um leão <span class=\"greek\">ζητῶν τίνα καταπιεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:8</a> (Damasc., Vi. Isid. 69 <span class=\"greek\">ὁ λέων καταπίνει τὸν ἄνθρωπον</span>).</p><p class=\"entry-text\"> ⓑ referente à água e às ondas, engolir, submergir (Polyb. 2, 41, 7 <span class=\"greek\">πόλις καταποθεῖσα ὑπὸ τ</span>. <span class=\"greek\">θαλάσσης</span>; Diod S 18, 35, 6; 26, 8; En 101:5; Philo, Virt. 201) na voz passiva, afogar-se (Ex 15:4 v.l. <span class=\"greek\">κατεπόθησαν ἐν ἐρυθρᾷ θαλάσσῃ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:29</a>.—Transferido a estados mentais e espirituais (cf. Philo, Gig. 13, Deus Imm. 181) <span class=\"greek\">μή πως τ</span>. <span class=\"greek\">περισσοτέρᾳ λύπῃ καταποθῇ</span> para que não seja consumido por tristeza excessiva <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:7</a> (TestAbr B 12 p. 117, 4 [Stone p. 82]).</p><p class=\"entry-text\"> ③ causar o fim de alguma coisa, absorver, aniquilar, em sentido figurado (cf. PGM 12, 44 <span class=\"greek\">κατέπιεν ὁ οὐρανός</span>; Ps 106:27; Philo, Leg. All. 3, 230; TestJud 21:7) na voz passiva, <span class=\"greek\">τὸ θνητὸν ὑπὸ τῆς ζωῆς</span>, aquilo que é mortal seja absorvido pela vida <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:4</a>. <span class=\"greek\">ὁ θάνατος εἰς νῖκος</span> a morte foi tragada pela vitória (segundo Is 25:8; veja também <span class=\"greek\">κέντρον</span> 1 e ARahlfs, ZNW 20, 1921, 183f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.54\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:54</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταπίπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">2º aoristo <span class=\"greek\">κατέπεσον</span>; particípio perfeito, genitivo plural, <span class=\"greek\">καταπεπτωκότων</span> 3 Macc 2:20 (veja <span class=\"greek\">πίπτω</span>; desde Homero) cair <span class=\"greek\">εἰς τὴν γῆν</span> cair por terra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:14</a> (TestJob 30:1; 40:4 <span class=\"greek\">ἐπὶ τὴν γῆν</span>). <span class=\"greek\">ἐπὶ τὴν πέτραν</span> (cf. Jos., Bell. 6, 64) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:6</a>. Em emprego absoluto, (Jos., Ant. 5, 27) <span class=\"greek\">καταπίπτειν νεκρόν</span> cair morto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:6</a> (cf. 4 Macc 4:11).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταπιστεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">confiar (veja <span class=\"greek\">πιστεύω</span>; Polyb.; Plut., Lys. 8, 3; pap; Mi 7:5) com dativo (Polyb. 2, 3, 3 al.) <span class=\"greek\">ἑαυτῷ</span> confiar em si mesmo Hm 9:10.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταπλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">1º aoristo <span class=\"greek\">κατέπλευσα</span> (veja <span class=\"greek\">πλέω</span>; desde Homero; inscrições, papiros) navegar do «alto-mar» em direção à costa, navegar rumo a, com <span class=\"greek\">εἰς</span> (X., Hell. 1, 7, 29 <span class=\"greek\">εἰς τ</span>. <span class=\"greek\">γῆν</span>; Appian, Basil. 1 §1 <span class=\"greek\">ἔς τινα αἰγιαλόν</span>; OGI 344, 2 <span class=\"greek\">εἰς βιθυνίαν</span>; Jos., Bell. 1, 610, Ant. 13, 86) <span class=\"greek\">εἰς τὴν χώραν τῶν Γερασηνῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:26</a>. Quanto à expressão <span class=\"greek\">κ</span>. <span class=\"greek\">εἰς τοὺς ἀγῶνας</span>, «ir às competições» (<span class=\"greek\">κ</span>. em sentido geral = «percorrer» SibOr 11, 203 <span class=\"greek\">κόσμον κ</span>.) 2 Cl 7:1, 3 veja Harnack, Lightfoot e Knopf acerca da passagem—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάπληξις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja o verbete seguinte; Tucídides e outros; Diod S 17, 84, 3; Celsus 6, 75; BGU 1209, 16 [23 a.C.]; 2 Esdr 3:3; Philo; Jos., Bell. 6, 89; Just., D. 7, 3) terror, pavor Dg 7:3.—DELG sob o verbete <span class=\"greek\">πλήσσω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταπλήσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">aoristo médio, 3ª pessoa do singular, <span class=\"greek\">κατεπλήξατο</span> (Just., A I, 56, 2). Na voz passiva: aoristo <span class=\"greek\">κατεπλάγην</span> LXX; particípio perfeito passivo <span class=\"greek\">καταπεπληγμένοι</span> 3 Macc 2:23 (veja <span class=\"greek\">πλήσσω</span>; Homero e outros; ins, pap, LXX, Just.; com várias acepções: «abater, aterrorizar, espantar»). Em sentido transferido de «abater»: assombrar, espantar <span class=\"greek\">τινά</span>, alguém (Philo, Omn. Prob. Lib. 100; Jos., Ant. 14, 370; Just., A I, 56, 2) IPol 3:1. Perfeito passivo <span class=\"greek\">καταπέπληγμαι</span> com sentido ativo, «ficar espantado, admirado» <span class=\"greek\">τὶ</span>, diante de alguma coisa (grego clássico; PSI 502, 8 [século III a.C.]; cf. 2 Macc 3:24; Philo, Post. Cai. 147; Jos., Vi. 120) <span class=\"greek\">οὗ καταπέπληγμαι τὴν ἐπιείκειαν</span> cuja mansidão me deixa admirado IPhld 1:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταπονέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">aoristo, 3ª pessoa do plural, <span class=\"greek\">κατεπόνησαν</span> (TestLevi 6:9) (veja <span class=\"greek\">πονέω</span>; Hippocr.; Polyb., Diod S 11, 6, 3; pap, LXX; TestLevi 6:9; Joseph.) provocar sofrimento mediante opressão: subjugar, atormentar, exaurir, oprimir <span class=\"greek\">τινά</span>, alguém B 20:2b; D 5:2b. No corpus aqui considerado, predomina o particípio presente passivo <span class=\"greek\">καταπονούμενος</span> (Aelian, VH 3, 27 <span class=\"greek\">ὑπὸ πενίας καταπονούμενος</span>; Jos., Bell. 2, 313, Ant. 7, 124) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:2</a> D. Acerca de Ló <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:7</a>.—Substantivado, <span class=\"greek\">ὁ καταπονούμενος</span> aquele que é oprimido, maltratado, exausto (UPZ 110, 88 [164 a.C.]) <span class=\"greek\">ποιεῖν ἐκδίκησιν τῷ κ</span>. assegurar que se faça justiça ao oprimido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:24</a>; <span class=\"greek\">πονεῖν ἐπὶ κ</span>. trabalhar em favor de quem é oprimido B 20:2a; D 5:2a.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταποντίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro <span class=\"greek\">καταποντιῶ</span> LXX; 1º aoristo <span class=\"greek\">κατεπόντισα</span> LXX; aoristo passivo <span class=\"greek\">κατεποντίσθην</span> (<span class=\"greek\">ποντίζω</span>, «lançar/submergir no mar»; Epicharmus [cerca de 480 a.C.]: Vorsokrat.5 23 B, 44a; Lysias, Demosth. et al.; Polyb., Diod S 14, 112, 1; PPetr II, 40 [a], 27 [século III a.C.]; LXX; Jos., Ant. 10, 122, C. Ap. 2, 245) «lançar ao mar» e, depois, em sentido geral, «afogar»; na voz passiva, «submergir, afogar-se» <span class=\"greek\">ἐν τῷ πελάγει τῆς θαλάσσης</span> ser submerso ou afogar-se em alto-mar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:6</a>. <span class=\"greek\">εἰς τὴν θάλασσαν</span> 1 Cl 46:8 (Plut., Tim. 13, 10 <span class=\"greek\">εἰς τὸ πέλαγος</span>; Ps.-Callisth. 1, 39, 5 <span class=\"greek\">εἰς βυθὸν θαλάσσης</span>). Em emprego absoluto, <span class=\"greek\">ἀρξάμενος καταποντίζεσθαι</span> quando começou a afundar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:30</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja o verbete seguinte; Ésquilo e outros; Ps.-Pla., Alc. 2, 143b; Polyb. 24, 8, 7; Diod S 1, 45, 2; Ael. Aristid. 33, 32 K.=51 p. 582 D.; SIG 1241, 1; PSI XI, 1219, 41 [século II d.C., escólio sobre Calímaco]; LXX, En, Test12Patr; GrBar 4:9, 15 [cristão]; Philo; Jos., Ant. 4, 118; 307; Just.) maldição, imprecação, em contraste com <span class=\"greek\">εὐλογία</span> (como em Dt 11:26; 30:1, 19; Sir 3:9; Philo, Det. Pot. Ins. 71) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:10</a>. <span class=\"greek\">ἀποδιδόναι κατάραν ἀντὶ κατάρας</span> retribuir maldição com maldição Pol 2:2. Referente a terra estéril, repleta de espinhos e abrolhos <span class=\"greek\">κατάρας ἐγγύς</span> quase amaldiçoada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:8</a> (cf. Gen 3:17.—<span class=\"greek\">κ</span>. <span class=\"greek\">ἐγγύς</span> como em Ael. Aristid. 26, 53 K.=14 p. 343 D.). Referente ao caminho da morte <span class=\"greek\">κατάρας μεστή</span> cheio de maldição B 20:1; D 5:1. Referente a pessoas <span class=\"greek\">κατάρας τέκνα</span> (cf. Sir 41:9 <span class=\"greek\">ἐὰν γεννηθῆτε εἰς κατάραν γεννηθήσεσθε</span>) amaldiçoados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:14</a>.—Em Paulo, referente aos adeptos das ordenanças mosaicas <span class=\"greek\">ὑπὸ κατάραν εἰσίν</span> estão debaixo de maldição (essa expressão corresponde a <span class=\"greek\">ἐξαποστελῶ</span> [isto é, o <span class=\"greek\">κύριος</span>] <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑμᾶς τ</span>. <span class=\"greek\">κατάραν</span> Mal 2:2; cf. Judg 9:57—<span class=\"greek\">κατάραν ὑφίστασθαι</span> Did., Gen. 209, 24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:10</a> (<span class=\"greek\">ὑπὸ κ</span>. <span class=\"greek\">φαίνονται εἶναι</span> Just., D. 95, 1; <span class=\"greek\">ὑπὸ κ</span>. <span class=\"greek\">γεγόνασιν</span> Did, Gen. 211, 11). Referente a Cristo: <span class=\"greek\">ἡμᾶς ἐξηγόρασεν ἐκ τῆς κ</span>. <span class=\"greek\">τοῦ νόμου</span> ele nos resgatou da maldição da lei versículo 13a. Abstrato empregado em lugar de concreto <span class=\"greek\">γενόμενος ὑπὲρ ἡμῶν κ</span>. tornando-se em nosso favor uma oferta associada à maldição (ou objeto de maldição) versículo 13b. Assim também <span class=\"greek\">ἐγὼ κατάρα ἐγεννήθην ἐνώπιον αὐτῶν πάντων</span> aos olhos de todos, nasci para ser amaldiçoado GJs 3:1.—DELG sob o verbete <span class=\"greek\">ἀρά</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταράομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">depoente médio; 1º aoristo <span class=\"greek\">κατηρασάμην</span>. Na voz passiva: aoristo, 3ª pessoa do singular, <span class=\"greek\">κατηράθη</span> (Just., D. 111, 2), optativo, 3ª pessoa do singular, <span class=\"greek\">καταραθείη</span> Job 3:6 e 24:1; perfeito, 3ª pessoa do plural, <span class=\"greek\">κεκατήρανται</span> Num 22, 6 e 24:9; particípio <span class=\"greek\">κεκατηραμένος</span> ou <span class=\"greek\">κατηραμένος</span> LXX (veja o verbete precedente; desde Homero; LXX, En; PsSol 3:9; TestSol 20:6; TestAbr A 14 p. 94, 17 [Stone p. 36]; TestJob 13:5; GrBar 4:8; Philo, Joseph., Just.) amaldiçoar, imprecar contra <span class=\"greek\">τινά</span>, alguém (Plut., Cato Min. 774 [32, 4] v.l.; Ps.-Lucian, Asinus 27; Gen 12:3; 27:29 al.; Philo, Det. Pot. Ins. 103; Test12Patr; Just., D. 139, 1 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:44</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:9</a>; 1 Cl 10:3 (Gen 12:3); uma árvore <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:21</a>. Com dativo <span class=\"greek\">τινί</span> (assim em Heródoto 4, 184; X., An. 7, 7, 48; Diod S 1, 45, 2; 14, 70, 2; EpJer 65; Philo, Fuga 73, Leg. All. 3, 65 <span class=\"greek\">τῷ ὄφει</span> [mas 75 <span class=\"greek\">τὸν ὄφιν</span>]; Jos., Bell. 3, 297, C. Ap. 1, 204; Just., D. 133, 6) amaldiçoar alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:44</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:28</a> v.l.; D 1:3. Em emprego absoluto, (Aristoph., Vesp. 614; Demosth. 18, 283) amaldiçoar (em contraste com <span class=\"greek\">εὐλογεῖν</span>, como em Philo, Rer. Div. Her. 177) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:14</a>; 1 Cl 15:3 (Ps 61:5); (em associação com <span class=\"greek\">ἀρνεῖσθαι</span> e <span class=\"greek\">ὀμνύναι</span>) Judaicon 333, 51=GHb 16—Particípio perfeito <span class=\"greek\">κατηραμένος</span> com sentido passivo (Plut., Lucull. 503 [18, 6]; 4 Km 9:34; Wsd 12:11; Just., D. 93, 4) <span class=\"greek\">οἱ κατηραμένοι</span> os amaldiçoados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:41</a>. <span class=\"greek\">οἱ κ</span>. <span class=\"greek\">ὑπὸ τοῦ θεοῦ</span> (cf. Dt 21:23; Herm. Wr. 2, 17a) 1 Cl 30:8. <span class=\"greek\">κατηραμένην</span>…<span class=\"greek\">τοῦ ὄφεως πίστιν</span> a fé maldita da serpente (isto é, associada a ela) AcPlCor 2:20 (cf. Gen. 3).—Quanto à bibliografia, veja o fim do verbete <span class=\"greek\">εὐλογέω</span>; também KLatte, Heil. Recht 1920, 61–96; B. 1481. JPedersen, Der Eid bei den Semiten 1914; veja especialmente as inscrições com maldições de Comagena (século I a.C.): OGI 383; e FDörner-TGöell, Arsameia am Nymphaios ’63, pp. 40–59 texto e tradução (bibliografia)—DELG sob o verbete <span class=\"greek\">ἀρά</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταργέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro <span class=\"greek\">καταργήσω</span>; 1º aoristo <span class=\"greek\">κατήργησα</span>; perfeito <span class=\"greek\">κατήργηκα</span>. Na voz passiva: 1º futuro <span class=\"greek\">καταργηθήσομαι</span>; 1º aoristo <span class=\"greek\">κατηργήθην</span>; perfeito <span class=\"greek\">κατήργημαι</span> (veja <span class=\"greek\">ἀργέω</span>; desde Eurípides, Phoen. 753; Polyb.; POxy 38, 7 [49/50 d.C.]; PFlor 176, 7; 218, 13; PStras 32, 7; 2 Esdr; TestSol [também PVindobBosw em 18:38]; AscIs 3:31; Just.).</p><p class=\"entry-text\"> ① fazer alguma coisa ficar improdutiva: esgotar, exaurir, desperdiçar referente a uma árvore <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν γῆν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:7</a> (cf. <span class=\"greek\">ἀργεῖ οὐδὲν ἀλλὰ καρποφορεῖ</span> OdeSol 11:23).</p><p class=\"entry-text\"> ② fazer algo perder seu poder ou eficácia: invalidar, tornar inoperante, em extensão figurada da acepção 1 (assim, sobretudo em Paulo e nos escritos que dele dependem; cf. Herm. Wr. 13, 7 <span class=\"greek\">κατάργησον τ</span>. <span class=\"greek\">σώματος τὰς αἰσθήσεις</span>; referente à alma de Jesus: <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ ἐπὶ κολάσεσιν πάθη</span> Iren. 1, 25, 1 [Harv. I 205, 4]) tornar ineficaz, anular <span class=\"greek\">τὴν πίστιν τοῦ θεοῦ</span> a fidelidade de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:3</a>. <span class=\"greek\">ἐπαγγελίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:17</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:14</a>; <span class=\"greek\">τὰ ὄντα κ</span>. reduzir a nada aquilo que (de fato) existe <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:28</a>. <span class=\"greek\">τὸν νόμον</span> invalidar a lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:15</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:31</a> (RThompson, ETh 63, ’87, 136–48, quanto a um suposto contexto rabínico; veja também <span class=\"greek\">ἵστημι</span> A4). Também em B, a respeito das ordenanças cultuais do AT, que perderam sua validade para os cristãos 5:6; 9:4; 16:2.</p><p class=\"entry-text\"> ③ fazer alguma coisa chegar ao fim ou deixar de existir: abolir, eliminar, pôr de lado <span class=\"greek\">τὶ</span>, alguma coisa <span class=\"greek\">τὰ τοῦ νηπίου</span> deixar para trás as atitudes de criança <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:11</a>. Referente a Deus ou a Cristo: Deus fará cessar tanto o estômago quanto os alimentos 6:13; pôr fim a <span class=\"greek\">πᾶσαν ἀρχήν</span>, <span class=\"greek\">ἐξουσίαν</span>, <span class=\"greek\">δύναμιν</span> 15:24. <span class=\"greek\">τὸν ἄνομον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:8</a>. <span class=\"greek\">τὸν καιρὸν τοῦ ἀνόμου</span> pôr fim ao tempo do iníquo (isto é, o diabo) B 15:5. <span class=\"greek\">τὸν θάνατον</span> quebrar o poder da morte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:10</a>; B 5:6; na voz passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:26</a> (MDahl, The Resurrection of the Body [1 Cor 15], ’62, 117–19). <span class=\"greek\">τὸν τὸ κράτος ἔχοντα τοῦ θανάτου</span> destruir aquele que tem o poder da morte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:14</a>. <span class=\"greek\">ἵνα καταργηθῇ τὸ σῶμα τ</span>. <span class=\"greek\">ἁμαρτίας</span> para que o corpo do pecado seja destruído <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:6</a>. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:14</a>, o sujeito pode ser <span class=\"greek\">ἡ παλαιὰ διαθήκη</span> ou, mais provavelmente (apesar de certas considerações gramaticais), <span class=\"greek\">κάλυμμα</span>; neste último caso, a acepção é «remover».—Na voz passiva, cessar, desaparecer <span class=\"greek\">προφητεία</span>, <span class=\"greek\">γνῶσις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:8</a>. <span class=\"greek\">τὸ ἐκ μέρους</span> aquilo que é parcial versículo 10. <span class=\"greek\">ἄρα κατήργηται τὸ σκάνδαλον τοῦ σταυροῦ</span> a cruz deixou de ser um obstáculo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:11</a>. <span class=\"greek\">πᾶς πόλεμος καταργεῖται</span> toda guerra chega ao fim IEph 13:2. <span class=\"greek\">καταργούμενος</span> destinados a perecer, referente aos <span class=\"greek\">ἄρχοντες τοῦ αἰῶνος τούτου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:6</a>. Referente ao resplendor no rosto de Moisés <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:7</a>. Substantivado, <span class=\"greek\">τὸ καταργούμενον</span>, aquilo que é transitório versículos 11, 13.</p><p class=\"entry-text\"> ④ libertar alguém de uma obrigação (com a qual já não mantém vínculo): ficar desobrigado, ser liberado. No corpus aqui considerado, na voz passiva, <span class=\"greek\">καταργοῦμαι ἀπό τινος</span> referente a uma mulher após a morte do marido <span class=\"greek\">κατήργηται ἀπὸ τοῦ νόμου τοῦ ἀνδρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:2</a>. Referente aos cristãos <span class=\"greek\">κ</span>. <span class=\"greek\">ἀπὸ τοῦ νόμου</span> ser libertado da lei versículo 6. Referente àqueles que buscam a justiça mediante a lei <span class=\"greek\">κ</span>. <span class=\"greek\">ἀπὸ Χριστοῦ</span> estar separado de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:4</a>.—Frisk, sob o verbete 2 <span class=\"greek\">ἀργός</span>; também DELG, sob o verbete <span class=\"greek\">ἔργον</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταριθμέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">infinitivo aoristo <span class=\"greek\">καταριθμῆσαι</span> (Just., D. 132, 1). Na voz passiva: aoristo, 3ª pessoa do plural, <span class=\"greek\">κατηριθμήθησαν</span> Hos 4:14 Theod.; particípio perfeito passivo <span class=\"greek\">κατηριθμημένος</span> (veja <span class=\"greek\">ἀριθμέω</span>; Eurípides, Platão e outros; ins, pap, LXX, Philo, Joseph., Just.).</p><p class=\"entry-text\"> ① enumerar, contar (Jos., Ant. 11, 73; Just., A I, 9, 4 al.) <span class=\"greek\">ὁ ἀριθμὸς ὁ κατηριθμημένος τῶν ἐκλεκτῶν</span> o número dos eleitos, que foi contado 1 Cl 59:2.</p><p class=\"entry-text\"> ② incluir como membro de um grupo, contar entre na voz passiva, pertencer ao grupo, com <span class=\"greek\">ἐν</span> (Pla., Polit. 266a al.; Diod S 4, 85, 5; 16, 83, 3; SIG 810, 24 <span class=\"greek\">ἀνδρὸς παρ</span>’ <span class=\"greek\">ὑμεῖν ἐν τοῖς ἐπιφανεστάτοις καταριθμουμένου</span>; UPZ 110, 99 [164 a.C.]; 2 Ch 31:19; Philo, Spec. Leg. 2, 118) referente ao traidor: <span class=\"greek\">κατηριθμημένος ἦν ἐν ἡμῖν</span> ele fazia parte de nosso número <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:17</a>.—DELG sob o verbete <span class=\"greek\">ἀριθμός</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταρρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">imperfeito <span class=\"greek\">κατέρρεον</span>; futuro, 3ª pessoa do plural, <span class=\"greek\">καταρρεύσουσιν</span> Jer 13:17 Sym.; aoristo, 3ª pessoa do plural, <span class=\"greek\">κατέρρευσαν</span> Is 64:1 Aq; perfeito, 3ª pessoa do singular, <span class=\"greek\">κατερρύηκεν</span> Jer 8:13 (veja <span class=\"greek\">ῥέω</span>; Homero e outros; PMagd 24, 5 [século III a.C.]; LXX; TestSol 17:3; JosAs 29:1 códice A em lugar de <span class=\"greek\">ἐρρύη</span>; ApcMos 20; Joseph.) escorrer, referente ao pus (Horapollo 2, 57) e à imundície ApcPt 11:26.—DELG sob o verbete <span class=\"greek\">ῥέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταρτίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro <span class=\"greek\">καταρτίσω</span>; 1º aoristo <span class=\"greek\">κατήρτισα</span>, voz média <span class=\"greek\">κατηρτισάμην</span>, 2ª pessoa do singular <span class=\"greek\">κατηρτίσω</span>. Na voz passiva: aoristo <span class=\"greek\">κατηρτίσθην</span> LXX; perfeito passivo <span class=\"greek\">κατήρτισμαι</span> (<span class=\"greek\">ἀρτίζω</span>, «aprontar, preparar»; veja o verbete seguinte; Heródoto e outros; ins, pap, LXX; TestSol 5:12 H).</p><p class=\"entry-text\"> ① pôr em condições de funcionar adequadamente: ordenar, restaurar.</p><p class=\"entry-text\"> ⓐ restabelecer a condição anterior, corrigir, reparar (desde Heródoto 5, 28; 106; Dionys. Hal. 3, 10) <span class=\"greek\">τὶ</span>, alguma coisa, por exemplo, redes (limpando-as, consertando-as ou dobrando-as) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:19</a> (cf. GWynne, Exp. 7th ser., 8, 1909, 282–85). Em sentido figurado, <span class=\"greek\">κ</span>. <span class=\"greek\">τινά</span>, restaurar alguém <span class=\"greek\">ἐν πνεύματι πραΰτητος</span> com espírito de mansidão, isto é, com brandura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:1</a>. Na voz passiva, <span class=\"greek\">καταρτίζεσθε</span>, «corrigi a vossa conduta» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:11</a>.</p><p class=\"entry-text\"> ⓑ pôr nas condições adequadas (cf. Epict. 3, 20, 10 referente a um treinador que ajusta partes do corpo), ajustar, completar, aperfeiçoar <span class=\"greek\">τὶ</span>, alguma coisa: <span class=\"greek\">καταρτίσαι τὰ ὑστερήματα τ</span>. <span class=\"greek\">πίστεως ὑμῶν</span> suprir quaisquer deficiências em vossa fé ou completar o que nela falta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:10</a>. <span class=\"greek\">τινά</span>, alguém: <span class=\"greek\">ὑμᾶς ἐν παντὶ ἀγαθῷ</span> vos aperfeiçoe em tudo o que é bom <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:21</a>. <span class=\"greek\">κατηρτισμένοι ἐν τῷ αὐτῷ νοὶ̈ καὶ ἐν τῇ αὐτῇ γνώμῃ</span> ajustados / aperfeiçoados no mesmo entendimento e na mesma convicção <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:10</a>. <span class=\"greek\">ἐν μιᾷ ὑποταγῇ</span> IEph 2:2. <span class=\"greek\">ἐν ἀκινήτῳ πίστει</span> ISm 1:1. Em emprego absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:10</a>. <span class=\"greek\">κατηρτισμένος</span> (inteiramente) instruído, exercitado (Polyb. 5, 2, 11 <span class=\"greek\">τ</span>. <span class=\"greek\">εἰρεσίαις κατηρτισμένοι</span>) <span class=\"greek\">κ</span>. <span class=\"greek\">πᾶς</span> (<span class=\"greek\">μαθητὴς</span>) <span class=\"greek\">ἔσται ὡς ὁ διδάσκαλος αὐτοῦ</span> quando estiver plenamente instruído, o discípulo será como o mestre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:40</a>. Veja Betz, Gal. 297 n. 43.</p><p class=\"entry-text\"> ② preparar para uma finalidade: preparar, fazer, criar, equipar.</p><p class=\"entry-text\"> ⓐ nas vozes ativa e passiva, referente a Deus (com <span class=\"greek\">ποιεῖν</span>) B 16:6. (Com <span class=\"greek\">κτίζειν</span>) <span class=\"greek\">τὰ πάντα</span> Hm 1:1. Na voz passiva, <span class=\"greek\">ὁ κόσμος κατηρτίσθη</span> Hv 2, 4, 1; também <span class=\"greek\">οἱ αἰῶνες</span> (veja <span class=\"greek\">αἰών</span> 3) <span class=\"greek\">ῥήματι θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:3</a>. <span class=\"greek\">κατηρτισμένος εἴς τι</span> feito, criado para alguma coisa: <span class=\"greek\">σκεύη ὀργῆς κατηρτισμένα εἰς ἀπώλειαν</span> vasos de ira, preparados para a destruição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:22</a>. <span class=\"greek\">ἄνθρωπος εἰς ἕνωσιν κατηρτισμένος</span> um homem voltado para a unidade (literalmente, «feito para» a unidade) IPhld 8:1.</p><p class=\"entry-text\"> ⓑ na voz média (PGM 4, 1147) <span class=\"greek\">καταρτίζεσθαί τί τινι</span> preparar alguma coisa para alguém <span class=\"greek\">σῶμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:5</a> (Ps 39:7 codd.: BSA). Com sentido reflexivo: para si mesmo <span class=\"greek\">κατηρτίσω αἶνον</span> preparaste louvor para ti mesmo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:16</a> (Ps 8:3).—DELG sob o verbete <span class=\"greek\">ἀραρίσκω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάρτισις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja o verbete precedente; Plut., Alex. 667 [7, 1] «treinamento»; cf. o mesmo autor, <span class=\"greek\">κατάρτυσις</span> Them. 112 [2, 7] com <span class=\"greek\">παιδεία</span>) o processo de aperfeiçoamento, maturação <span class=\"greek\">εὐχόμεθα τὴν ὑμῶν κ</span>. oramos por vosso amadurecimento («pelo aperfeiçoamento de vosso caráter», segundo Goodspeed) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:9</a>.—DELG sob o verbete <span class=\"greek\">ἀραρίσκω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταρτισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja os dois verbetes precedentes; como termo médico [Soranus 150, 8]: «redução de um osso», etc. Entretanto, em sentido mais geral, PTebt 33, 12 [112 a.C.] «preparação» <span class=\"greek\">αὐλῆς</span>; cf. CMRDM 1, 121; veja New Docs 3, 70, nº 42; PRyl 127, 28; Sym. Is 38:12 «restauração») acepção figurada ampliada (não documentada em inscrições nem em papiros) preparação, capacitação <span class=\"greek\">εἴς τι</span>, para alguma coisa <span class=\"greek\">πρὸς τὸν κ</span>. <span class=\"greek\">τῶν ἁγίων εἰς ἔργον διακονίας</span> capacitar o povo de Deus (literalmente, «os santos») para o serviço <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:12</a>, embora «treinamento» e «disciplina» (L-S-J-M) mereçam consideração como equivalentes de <span class=\"greek\">κ</span>.—DELG sob o verbete <span class=\"greek\">ἀραρίσκω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατασβέννυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro, 3ª pessoa do singular, <span class=\"greek\">κατασβέσει</span> Pr 15:18 e 28:2; 1º aoristo, 3ª pessoa do singular, <span class=\"greek\">κατέσβεσεν</span> 4 Macc 16:4, infinitivo <span class=\"greek\">κατασβέσαι</span> (veja <span class=\"greek\">σβέννυμι</span>; Homero e outros; PGM 12, 57 conforme restaurado por Dieterich; LXX; Philo, Aet. M. 91) apagar, extinguir <span class=\"greek\">τὶ</span>, alguma coisa <span class=\"greek\">τὸ πῦρ</span> (Il. 21, 381) MPol 16:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατασείω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">1º aoristo <span class=\"greek\">κατέσεισα</span> (veja <span class=\"greek\">σείω</span>; Tucídides e outros; 1 Macc 6:38; Philo, Joseph.) no corpus aqui considerado (Atos), sempre empregado com <span class=\"greek\">χείρ</span>, «fazer um gesto».</p><p class=\"entry-text\"> ① fazer movimentos rápidos, agitar, acenar rapidamente, com acusativo <span class=\"greek\">τὴν χεῖρα</span> (Vi. Aesopi W 87 P. <span class=\"greek\">τὴν χεῖρα τῷ ὄχλῳ κατασείσας</span>; Philo, De Jos. 211, Leg. ad Gai. 181 <span class=\"greek\">τὴν δεξιὰν χεῖρα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:33</a>, na tentativa de chamar a atenção. Dessa acepção passa-se facilmente a</p><p class=\"entry-text\"> ② sinalizar mediante gesto, fazer um sinal, com dativo <span class=\"greek\">τῇ χειρί</span> (Polyb. 1, 78, 3; Jos., Ant. 4, 323; 8, 275) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:16</a>. Outro dativo pode indicar a pessoa ou as pessoas às quais o sinal se destina (cf. X., Cyr. 5, 4, 4 <span class=\"greek\">κατασείω τινί</span>; Jos., Ant. 17, 257. De modo semelhante, PGM 5, 453 <span class=\"greek\">κ</span>. <span class=\"greek\">τῷ λύχνῳ</span>=«fazer um gesto em direção à lâmpada») <span class=\"greek\">κατέσεισεν τ</span>. <span class=\"greek\">χειρὶ τ</span>. <span class=\"greek\">λαῷ</span> 21:40. A finalidade do sinal é indicada pelo infinitivo (veja Apiano, Bell. Civ. 4, 2 §5 <span class=\"greek\">ἥκειν</span> e Josefo na passagem citada, mas não em Ant. 8, 275) <span class=\"greek\">κατασείσας αὐτοῖς τ</span>. <span class=\"greek\">χειρὶ σιγᾶν</span> fez-lhes sinal (com a mão) para que se calassem 12:17.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0192-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατασκάπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">σκάπτω</span>) futuro <span class=\"greek\">κατασκάψω</span> LXX; 1º aoristo <span class=\"greek\">κατέσκαψα</span>. Na voz passiva: futuro, 3ª pessoa do singular, <span class=\"greek\">κατασκαφήσεται</span> LXX; aoristo <span class=\"greek\">κατεσκάφην</span>; particípio perfeito <span class=\"greek\">κατεσκαμμένος</span> LXX derrubar, arrasar até os alicerces (assim nos trágicos, em Heródoto e outros; ins, LXX; Philo, Leg. ad Gai. 132; Ath., R. 19 p. 72, 29) <span class=\"greek\">τὶ</span>, alguma coisa, como cidades (Hdt. 7, 156; Ael. Aristid. 32 p. 604 D.; SIG 344, 7; Jos., Ant. 4, 313; 8, 128) 1 Cl 6:4 variante textual. Altares <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:3</a> (3 Km 19:10). <span class=\"greek\">τὰ κατεσκαμμένα αὐτῆς</span> suas partes que haviam sido derrubadas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:16</a> (veja <span class=\"greek\">ἀνασκάπτω</span> e <span class=\"greek\">καταστρέφω</span> 2).—M-M.</p></section></article>\n"};
